mapper.select:
SELECT EXISTS(
SELECT 1 FROM warehouse.goods_receipts
WHERE supplier_id = #{supplierId}
AND invoice_number = #{documentNumber}
AND status NOT IN ('REJECTED', 'CANCELLED')

    AND id != #{excludeReceiptId}

)

SELECT EXISTS(
SELECT 1 FROM warehouse.goods_receipts
WHERE invoice_number = #{documentNumber}
AND LOWER(TRIM(supplier_name_snapshot)) = LOWER(TRIM(#{supplierName}))
AND status NOT IN ('REJECTED', 'CANCELLED')

    AND id != #{excludeReceiptId}

)

SELECT gr.id
FROM warehouse.goods_receipts gr
WHERE gr.document_type = 'DELIVERY_NOTE'
AND gr.invoice_number = #{number}
AND gr.status NOT IN ('REJECTED', 'CANCELLED')

    AND gr.supplier_id = #{supplierId}


    AND gr.id != #{excludeReceiptId}

ORDER BY gr.id
LIMIT 1

SELECT COALESCE(-SUM(m.quantity), 0)
  FROM warehouse.stock_movements m
 WHERE m.order_item_id = #{orderItemId}
